/** Owned synthetic note writer with concurrent read-side auth/timeline/scheduler probes. */
import assert from 'node:assert/strict';
import { mkdirSync,writeFileSync } from 'node:fs';import fs from 'node:fs/promises';
import { join } from 'node:path';import { spawn } from 'node:child_process';import { once } from 'node:events';
import { monitorEventLoopDelay,performance } from 'node:perf_hooks';
import { initDatabase,getDb,closeDatabase } from '../../src/db/connection.js';
import { captureNoteIndexBinding } from '../../src/note-retrieval/access.js';
import { createWebSession,getWebSession } from '../../src/db/web-sessions.js';
import { storeChatMetadata,storeMessage } from '../../src/db/messages.js';
import { getTimelineResponse } from '../../src/channels/web/timeline-service.js';
import { getDueTasks } from '../../src/db/tasks.js';
import { assertPathWithinTestFilesystemIsolation } from '../../scripts/test-filesystem-isolation.js';
const workspace=process.env.PICLAW_WORKSPACE!;assertPathWithinTestFilesystemIsolation(workspace,process.env,{allowRoot:false});assert.equal(process.env.PICLAW_DB_IN_MEMORY,'0');
const writer=process.argv[2]==='writer',instrument=process.argv.includes('instrument'),mode=process.argv[2]??'plain';
const metrics:Record<string,{calls:number;ms:number;codeUnits?:number}>={};const entry=(k:string)=>metrics[k]??={calls:0,ms:0};
let network=0;const deny=()=>{network++;throw Error('no external I/O')};globalThis.fetch=Object.assign(deny,{preconnect:deny})as typeof fetch;
if(writer){
 initDatabase();const db=getDb(),prepare=db.prepare,query=db.query,transaction=db.transaction,parse=JSON.parse,stringify=JSON.stringify,open=fs.open;let opens=0;
 fs.open=(async(...args:Parameters<typeof fs.open>)=>{opens++;return Reflect.apply(open,fs,args)})as typeof fs.open;
 const time=<T>(k:string,f:()=>T)=>{const start=performance.now();try{return f()}finally{entry(k).calls++;entry(k).ms+=performance.now()-start}};
 const proxies=new WeakMap<object,object>();const wrap=(s:any)=>{const prior=proxies.get(s);if(prior)return prior;const p=new Proxy(s,{get(t,k){if(!['all','get','run'].includes(String(k)))return Reflect.get(t,k,t);return(...args:unknown[])=>time('SQL.'+String(k),()=>Reflect.apply(t[k],t,args))}});proxies.set(s,p);return p};
 if(instrument){db.prepare=((...args:Parameters<typeof prepare>)=>wrap(time('SQL.prepare',()=>Reflect.apply(prepare,db,args))))as typeof prepare;db.query=((...args:Parameters<typeof query>)=>wrap(time('SQL.query',()=>Reflect.apply(query,db,args))))as typeof query;db.transaction=((...args:Parameters<typeof transaction>)=>{const f=Reflect.apply(transaction,db,args);const wrapped=(...p:unknown[])=>time('SQL.transaction',()=>Reflect.apply(f,db,p));for(const k of['immediate','deferred','exclusive'])Object.defineProperty(wrapped,k,{value:(...p:unknown[])=>time('SQL.transaction.'+k,()=>Reflect.apply(f[k],f,p))});return wrapped})as typeof transaction;JSON.parse=((...a:Parameters<typeof parse>)=>{const r=time('JSON.parse',()=>parse(...a));entry('JSON.parse').codeUnits=(entry('JSON.parse').codeUnits??0)+a[0].length;return r})as typeof parse;JSON.stringify=((...a:Parameters<typeof stringify>)=>{const r=time('JSON.stringify',()=>stringify(...a));entry('JSON.stringify').codeUnits=(entry('JSON.stringify').codeUnits??0)+(r?.length??0);return r})as typeof stringify;}
 const loop=monitorEventLoopDelay({resolution:1});loop.enable();await Bun.sleep(10);const cpu=process.cpuUsage(),start=performance.now();
 try{const{runNoteIndexPhase}=await import('../../src/note-retrieval/coordinator.js');await runNoteIndexPhase();await Bun.sleep(10);loop.disable();const row=db.query('SELECT count(*) AS n FROM note_retrieval_sources').get()as{n:number};assert.equal(row.n,100);console.log(stringify({kind:'writer',wallMs:performance.now()-start,cpu:process.cpuUsage(cpu),sourceOpens:opens,metrics:instrument?metrics:null,eventLoop:{samples:loop.count,maxMs:loop.max/1e6},memory:process.memoryUsage(),files:row.n,network}));}finally{db.prepare=prepare;db.query=query;db.transaction=transaction;JSON.parse=parse;JSON.stringify=stringify;fs.open=open;loop.disable();closeDatabase()}
}else{
 assert(['plain','instrument','cpu'].includes(mode));mkdirSync(join(workspace,'.piclaw'),{recursive:true});writeFileSync(join(workspace,'.piclaw/config.json'),JSON.stringify({domains:{access:{mode:'single-user'}}}));mkdirSync(join(workspace,'notes'),{recursive:true});
 for(let n=0;n<100;n++)writeFileSync(join(workspace,'notes',`synthetic-${n}.md`),`# Synthetic note ${n}\n\n`+Array.from({length:20},(_,i)=>`## Section ${i}\n\nObserved synthetic workload entry ${n}/${i}; no user information.\n\n`).join(''));
 initDatabase();const db=getDb();storeChatMetadata('web:synthetic','2026-01-01T00:00:00.000Z');db.transaction(()=>{for(let n=0;n<100;n++)storeMessage({id:'note-profile-message-'+n,chat_jid:'web:synthetic',sender:'synthetic',sender_name:'Synthetic',content:'synthetic row',timestamp:new Date(1700000000000+n).toISOString(),is_from_me:false,is_bot_message:false})}).immediate();createWebSession('synthetic-probe-cookie','default',3600,'totp');
 const args=['--no-env-file'];if(mode==='cpu'){assert(process.env.PICLAW_NOTE_PROFILE_DIR);args.push('--cpu-prof','--cpu-prof-dir='+process.env.PICLAW_NOTE_PROFILE_DIR,'--cpu-prof-name='+process.env.PICLAW_NOTE_PROFILE_NAME)}args.push(import.meta.path,'writer');if(mode==='instrument')args.push('instrument');
 const child=spawn(process.execPath,args,{env:process.env,cwd:process.cwd(),stdio:['ignore','pipe','pipe','pipe']});let out='',err='',finished=false;child.stdout!.on('data',b=>out+=b);child.stderr!.on('data',b=>err+=b);const done=once(child,'exit');done.then(()=>{finished=true});(child.stdio[3]as any).end(JSON.stringify(captureNoteIndexBinding()));const timer=setTimeout(()=>child.kill('SIGTERM'),30000);
 const loop=monitorEventLoopDelay({resolution:1});loop.enable();const batches:number[]=[],cpu=process.cpuUsage(),start=performance.now();
 try{while(!finished){const tick=performance.now();assert.equal(getWebSession('synthetic-probe-cookie')?.user_id,'default');assert.equal((getTimelineResponse('web:synthetic',50).body as any).posts.length,50);assert.deepEqual(getDueTasks(),[]);batches.push(performance.now()-tick);await Bun.sleep(5);}const[exit]=await done;assert.equal(exit,0,err);await Bun.sleep(10);loop.disable();const worker=JSON.parse(out.trim().split('\n').at(-1)!);assert.equal(worker.files,100);assert.equal(worker.sourceOpens,200);assert.equal(worker.network,0);const publication=db.query('SELECT staging,writer_pid,state FROM note_retrieval_state WHERE id=1').get();assert.deepEqual(publication,{staging:null,writer_pid:null,state:'ready'});assert.deepEqual(db.query('PRAGMA quick_check').get(),{quick_check:'ok'});console.log(JSON.stringify({mode,runtime:Bun.version,fixture:{files:100,sectionsEach:20},writer:worker,parent:{wallMs:performance.now()-start,cpu:process.cpuUsage(cpu),requestProbeBatches:batches.length,batchMs:batches,eventLoop:{samples:loop.count,maxMs:loop.max/1e6,meanMs:loop.mean/1e6},memory:process.memoryUsage()},publication,network,scope:'Actual inherited-binding note writer and concurrent parent auth/timeline/scheduler due-task reads; no scheduler task/provider execution, live state or production HTTP middleware. Writer profile includes child startup/schema; method timings inclusive.'}));}finally{clearTimeout(timer);loop.disable();if(!finished){child.kill('SIGTERM');await done}closeDatabase()}
}
